using FluentAssertions; using Sigov.Domain.Agro; using Sigov.Domain.Agro.Enums; using Xunit;
namespace Sigov.UnitTests.Agro; public sealed class AgroFeiranteRulesTests{[Fact] public void Feirante_exige_produtor_ou_pessoa()=>FluentActions.Invoking(()=>new Feirante(1,1,1,null,null,"C1",false,null,AgroFeiranteSituacao.CADASTRADO)).Should().Throw<ArgumentException>(); [Fact] public void Feirante_nao_autorizado_nao_recebe_banca_ativa(){var f=new Feirante(1,1,1,1,null,"C1",false,null,AgroFeiranteSituacao.CADASTRADO); FluentActions.Invoking(()=>f.ValidarBancaAtiva()).Should().Throw<InvalidOperationException>();}}
